content:
/* 读书笔记数据源
 * 新增一本书：在 books 数组里加一个对象（id 唯一）。
 * 每本书 chapters 里的每一项对应一章，字段说明见 README.md。
 */
window.READING_DATA = {
  libraryName: '我的书架',
  books: [
    {
      id: 'xlw',
      title: '效率为王',
      fullTitle: '《效率为王》：存量时代企业经营的核心命题',
      author: '卫哲',
      role: '阿里前 CEO · 嘉御资本创始合伙人',
      readDate: '2026-08 读完',
      cover: { from: '#1e4158', to: '#3a7ca5', accent: '#ffd166' },
      tagline: '增量市场拼规模，存量市场拼效率',
      keywords: ['存量经济', '组织效率', '现金流', '战略罗盘', '个人成长'],
      status: '在读',
      summary: [
        '《效率为王》是阿里前 CEO、嘉御资本创始合伙人卫哲的著作，聚焦存量时代企业经营的核心命题：增量市场拼规模，存量市场拼效率。',
        '作者拥有横跨投行、跨国零售、互联网、股权投资的完整商业履历，亲历多轮商业周期、见证大量企业的成败，依托数十年一线管理与投资实战经验，拆解出个人、组织、运营、资产、战略、技术、创新、出海等多维度的效率提升方法论。',
        '全书十章层层递进：先立起\u201c存量时代效率为王\u201d的整体认知，再依次拆解领导、组织、运营、资产、战略、技术、创新、出海八大层面的效率打法，最后落到个人成长效率。无论是创业者、企业管理者还是普通职场人，都能从中拿到能直接上手的方法。'
      ],
      chapters: [
        {
          id: 'ch01',
          no: 1,
          title: '存量时代，效率为王',
          tagline: '增量拼规模，存量拼效率',
          keywords: ['经营油耗', '多快好省', '核心效率指标'],
          audio: null,
          mindmap: {
            t: '第一章 存量时代，效率为王',
            c: [
              {
                t: '核心命题',
                c: [
                  { t: '增量市场拼规模：先抢点位，车速为王' },
                  { t: '存量市场拼效率：资源更少、成本更贵，油耗为王' },
                  { t: '想要活得久、走得远，必须精打细算' }
                ]
              },
              {
                t: '经营油耗：四个关键点',
                c: [
                  { t: '车子性能 = 商业模式\n搭建低损耗模式，从源头省成本' },
                  { t: '赛道 = 行业选择\n选对顺畅赛道，避开内卷"烧钱"地带' },
                  { t: '驾驶员 = 经营者\n决策与运营决定能否少走弯路' },
                  { t: '载货体量 = 规模\n需求饱和，小体量高频运转更赚钱' }
                ]
              },
              {
                t: '客户第一：多、快、好、省',
                c: [
                  { t: '靠"多"：淘宝\n品类做到同行十倍' },
                  { t: '靠"快"：京东\n自建物流，三日达→当日达' },
                  { t: '靠"好"：唯品会\n大牌正品特卖，品质信任' },
                  { t: '靠"省"：拼多多\n拼团砍中间商，9块9包邮薄利多销' },
                  { t: '反例：共享单车\n盲目铺车，忽略折旧运维，大批倒闭' }
                ]
              },
              {
                t: '效率必须长期可持续',
                c: [
                  { t: '不能只看短期爆发' },
                  { t: '追求可持续的精细化效率' }
                ]
              },
              {
                t: '怎么衡量效率',
                c: [
                  { t: '找准第一核心效率指标\n依据最大开销来定' },
                  { t: '例：互联网=人均效能\n电商品牌=营销ROI' },
                  { t: '三种对比\n纵向自我、内部横向、对标同行' }
                ]
              }
            ]
          },
          notes: [
            { h: '核心命题', items: ['增量市场拼规模，存量市场拼效率', '从"拼车速"转向"拼油耗"：资源变少、成本变贵，必须精打细算'] },
            { h: '决定经营"油耗"的四个关键点', items: ['车子性能→商业模式：搭建低损耗经营模式，从源头节约成本', '赛道→行业选择：选对顺畅赛道阻力小；内卷赛道处处是坑、格外烧钱', '驾驶员→企业经营者：决策与运营水平直接决定少走弯路', '载货体量→规模：需求饱和，大车常空载、小面包车趟趟满载高频运转。存量时代绝不盲目扩张，合适远比做大重要'] },
            { h: '客户第一：多快好省（须可量化）', items: ['多：淘宝——商品品类做到同行十倍的硬性标准', '快：京东——自建物流，从三日达做到当日达', '好：唯品会——专注大牌正品特卖，靠品质优势获信任', '省：拼多多——砍中间商、拼团模式，9块9包邮薄利多销', '反面案例：共享单车只顾铺车扩张、忽略折旧运维等长期成本，最终大批倒闭', '结论：追求的效率必须是长期可持续的，不能只看短期爆发'] },
            { h: '精准衡量企业效率', items: ['找准自家第一核心效率指标，依据最大开销来定（互联网=人均效能；电商品牌=营销ROI）', '三种对比：和过去的自己纵向比、部门间横向比、对标同行，核心效率远超行业平均才算站稳'] }
          ]
        },
        {
          id: 'ch02',
          no: 2,
          title: '领导效率',
          tagline: '领导权不等于领导力，道、理、术三层进阶',
          keywords: ['自我驱动力', '时间管理', '道·理·术'],
          audio: null,
          mindmap: {
            t: '第二章 领导效率',
            c: [
              {
                t: '员工管理三要点',
                c: [
                  { t: '激发自我驱动力\n成就感 + 乐趣' },
                  { t: '适度激励\n了解诉求，助其达成目标' },
                  { t: '制度约束 → 自我约束\n建立对公司的信任' },
                  { t: '自我反问三问\n自驱举措·激励到位·束缚过多?' }
                ]
              },
              {
                t: '自我管理：时间管理',
                c: [
                  { t: '尽量消灭碎片化时间' },
                  { t: '任务合理分配 + 严格执行\n形成闭环' }
                ]
              },
              {
                t: '领导权 ≠ 领导力',
                c: [
                  { t: '领导权 = 职位赋予' },
                  { t: '领导力 = 员工发自内心愿意追随' },
                  { t: '领导力的作用远大于领导权' }
                ]
              },
              {
                t: '建立领导力：两点',
                c: [
                  { t: '坚守使命\n危机与诱惑下保持初心、言行一致' },
                  { t: '传递正确价值观\n明确底线，对内外行动始终贯彻' }
                ]
              },
              {
                t: '道：管理底层逻辑（十六字）',
                c: [
                  { t: '动之以情\n情感凝聚团队' },
                  { t: '晓之以理\n讲清愿景，相信共同未来' },
                  { t: '诱之以利\n利益回报，持续激发动力' },
                  { t: '绳之以法\n触碰底线，依规捍卫价值观' }
                ]
              },
              {
                t: '理：四大核心原则',
                c: [
                  { t: '解决下属解决不了的问题' },
                  { t: '教会下属解决问题的能力' },
                  { t: '承担下属承担不了的责任' },
                  { t: '想到下属想不到的激励' },
                  { t: '初创做前两件\n长期发展侧重后两件' }
                ]
              },
              {
                t: '术：实操四法',
                c: [
                  { t: '可跨级了解真实情况\n绝不跨级下达任务' },
                  { t: '开会最后发言\n会上至少表扬一次' },
                  { t: '不让自己成为唯一\n发现问题的人' },
                  { t: '提问比直接给答案更重要\n引导团队自己找到办法' }
                ]
              }
            ]
          },
          notes: [
            { h: '员工管理三要点', items: ['激发自我驱动力：让员工在工作里获得成就感、感受到乐趣，自发提升热情与效率', '做好适度激励：了解团队每个人的诉求，帮助大家实现个人目标', '把硬性制度约束，逐步转化为自我约束，以此建立员工对公司的信任', '管理者要常自问：有何自驱举措？激励是否到位？是否给了过多束缚？'] },
            { h: '领导者的时间管理', items: ['时间是管理者最宝贵的资产', '第一，尽量消灭碎片化时间；第二，做好时间规划与闭环管理，任务合理分配并严格执行'] },
            { h: '领导权 ≠ 领导力', items: ['领导权是职位赋予的；领导力是员工发自内心愿意追随你的内在力量，实际作用远大于领导权'] },
            { h: '建立领导力', items: ['坚守使命：行业充满变数与诱惑，能否坚守初心、言行一致是关键', '传递正确价值观：明确底线（什么事绝对不能做），并在对内对外实际行动中始终贯彻'] },
            { h: '好领导之"道"：管理底层逻辑十六字', items: ['动之以情：先用情感凝聚团队', '晓之以理：讲清愿景，让大家相信共同的未来', '诱之以利：适时利益回报，持续激发动力', '绳之以法：有人触碰底线，依规处理，捍卫企业价值观'] },
            { h: '好领导之"理"：四大核心原则', items: ['解决下属解决不了的问题；教会下属解决问题的能力', '承担下属承担不了的责任；想到下属想不到的激励', '创业初期重点做前两件；企业长期发展侧重后两点以增强凝聚力'] },
            { h: '好领导之"术"：四条实操方法', items: ['可以跨级了解真实情况，但绝不跨级下达任务，所有指令逐级传递', '开会最后一个发言，会上至少表扬一次：先听完所有人想法再输出观点', '不要让自己成为唯一发现问题的人：优先让团队解决，搞不定再出手', '提问比直接给答案更重要：引导团队自己发现问题、找出办法'] },
            { h: '小结', items: ['悟透"道"凝聚人心，恪守"理"做好表率，用好"术"优化管理——三重境界，即是出色的管理者'] }
          ]
        },
        {
          id: 'ch03',
          no: 3,
          title: '组织效率',
          tagline: '选好人、育好人，让组织能持续批量培养干部',
          keywords: ['招聘·培训·考核', '批量培养干部', '搭班子', '价值观'],
          audio: null,
          mindmap: {
            t: '第三章 组织效率',
            c: [
              {
                t: '三步法：招聘 / 培训 / 考核',
                c: [
                  {
                    t: '招聘',
                    c: [
                      { t: '不轻易下放招聘权\n跨两级参与，降用人失误' },
                      { t: '考察文化、气质契合度\n价值观匹配是基础' },
                      { t: '人才级差设计\n基层选偏低薪者激发潜能\n高端人才降薪考察' }
                    ]
                  },
                  {
                    t: '培训',
                    c: [
                      { t: '三类人群：新员工\n空降干部、内部新晋升管理者' },
                      { t: '业务骨干担任内部讲师' },
                      { t: '难度强度高于实际工作\n回到岗位更从容' }
                    ]
                  },
                  {
                    t: '考核',
                    c: [
                      { t: '按岗位设合理频次' },
                      { t: '三对一考核：直属上级\n上级的上级 + HR，防主观偏差' },
                      { t: '不只业绩：评估团队成长\n与价值观践行' },
                      { t: '用好结果：激励与淘汰\n如271末位淘汰，灵活调整' }
                    ]
                  }
                ]
              },
              {
                t: '组织建设成果 = 批量培养干部',
                c: [
                  { t: '干部三来源\n内部培养·外部引进·先引后培' },
                  { t: '红绿灯机制\n绿=胜任 / 黄=待提升 / 红=调整' },
                  { t: '四项计划\n目标量化·职责明确\n晋升加团队分·干部轮岗' }
                ]
              },
              {
                t: '组织顶层：搭班子',
                c: [
                  { t: '高层班子 = 企业的刹车系统\n防止创始人一意孤行' },
                  { t: '初创期：先搭班子，再定战略' },
                  { t: '成长期：先明确战略，再匹配人才' },
                  { t: '四原则：性别、年龄、文理均衡\n动态调整，持续优化' }
                ]
              },
              {
                t: '价值观落地',
                c: [
                  { t: '对外：员工做事的底线' },
                  { t: '对内：团队相处的准则' },
                  { t: '拆成具体行为标准\n与考核、晋升挂钩，有奖有罚' }
                ]
              }
            ]
          },
          notes: [
            { h: '提升组织效率三大要素', items: ['招聘——高效团队的源头：很多企业人员流失率高，根源就在招人环节', '培训——让关键人群快速胜任、持续成长', '考核——用对机制，选优汰劣'] },
            { h: '做好招聘的三点要求', items: ['不轻易下放招聘权限，尤其不能交给不理解公司战略的人；招聘尽量跨两级参与', '重点考察候选人与企业文化、气质的契合度：能力重要，价值观匹配是基础', '做好人才级差设计：基层可招上一份薪资偏低者（易获成就感、激发潜能）；引进高端人才可适当降薪考察，看其能否经受名利考验'] },
            { h: '有效的培训', items: ['重点抓三类人群：新员工、空降的新干部、内部提拔的新晋管理者', '让业务能力最强的骨干担任内部讲师，不能只把优秀人才放在一线埋头干活', '培训难度和强度最好高于实际工作：高强度训练后回到岗位更从容顺手'] },
            { h: '做好考核要解决四个问题', items: ['按不同岗位设置合理考核频次', '推荐三对一考核：直接上级+上级的领导+HR三方共同考评，避免单人主观偏差，也方便发现基层人才', '考核不能只看业绩，还要评估团队成长、价值观践行情况', '用好考核结果做好激励与淘汰（如271末位淘汰制，结合企业情况灵活调整）'] },
            { h: '组织建设成果=能否批量培养干部', items: ['干部来源：内部培养、外部引进；新兴领域可先引后培，但最终要建立自己的梯队', '红绿灯机制评估：绿灯胜任、黄灯待提升、红灯及时调整', '四项计划：培养目标量化（每年输出多少层级人才）；明确各层级职责（如M1）；晋升考核加入"团队分"；推行干部轮岗（横+纵，做好周期规划）'] },
            { h: '组织顶层：搭班子', items: ['企业如汽车，既要有发动机也要有刹车系统——高层班子就是刹车系统，防止创始人一意孤行', '初创期：先搭班子，再定战略；成长期：先明确战略，再匹配人才', '搭班子四原则：性别、年龄、文理背景均衡搭配；最重要的是根据战略变化动态调整'] },
            { h: '价值观落地', items: ['价值观不能是空洞口号：对外明确员工做事底线，对内明确团队相处准则', '把每一条价值观拆解成具体可执行的行为标准，与绩效考核、晋升挂钩，有奖有罚，长期坚持才能真正深入内心'] }
          ]
        },
        {
          id: 'ch04',
          no: 4,
          title: '运营效率',
          tagline: '远离大公司病，会议、报告、压力测试提效',
          keywords: ['反大公司病', '会议管理', '报告体系', '压力测试'],
          audio: null,
          mindmap: {
            t: '第四章 运营效率',
            c: [
              {
                t: '远离大公司病',
                c: [
                  { t: '症状：机构臃肿、层级过多\n职责模糊、流程繁琐' },
                  { t: '控制官兵比例：1:7 到 1:9' },
                  { t: '控制管理层级\n每多一层就多一层信息偏差\n核心部门尤其精简' }
                ]
              },
              {
                t: '避免官僚主义',
                c: [
                  { t: '风险管控三环节\n事前·事中·事后\n只重点管控关键节点' },
                  { t: '不搞秋后算账' },
                  { t: '精简审批流程\n砍掉不承担责任的签字节点' }
                ]
              },
              {
                t: '开好会议',
                c: [
                  { t: '三种类型\n决策会·协调会·务虚会' },
                  { t: '会前：议题提前发，提前准备' },
                  { t: '会中：专人纪要+责任人\n主持人可轮岗\n领导最后总结' },
                  { t: '会后：督办跟进\n下次会议复盘，形成闭环' },
                  { t: '频率按业务定，筛选参会者\n无输出不列席' }
                ]
              },
              {
                t: '报告体系',
                c: [
                  { t: '固定周期\n周报·月报·季报·年报' },
                  { t: '明确内容\n财务·客户健康度·团队健康度' },
                  { t: '统一数据口径\n可设商业分析专员专责' }
                ]
              },
              {
                t: '压力测试',
                c: [
                  { t: '先定目标，拆解到月周日\n最小时间单元' },
                  { t: '设偏高有挑战性的目标\n一次性暴露组织潜藏问题' },
                  { t: '五步：定性梳理困难→量化\n→提资源需求→时间计划\n→对齐进度，集中解决' },
                  { t: '约一个月可见运营效率提升' }
                ]
              }
            ]
